// "Create a save" support. A Wild World town (map, houses, buildings) is generated by the game,
// so a new save is built from a template: any valid save registered once and kept on the device.
import { AcwwSave } from './core/save';
import { VILLAGERS } from './core/data';

const DB = 'feuille-template', STORE = 'tpl', KEY = 'base';

function open(): Promise<IDBDatabase> {
  return new Promise((res, rej) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => r.result.createObjectStore(STORE);
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}

export async function getTemplate(): Promise<Uint8Array | null> {
  try {
    const db = await open();
    return await new Promise(res => {
      const q = db.transaction(STORE).objectStore(STORE).get(KEY);
      q.onsuccess = () => res(q.result ? new Uint8Array(q.result as ArrayBuffer) : null);
      q.onerror = () => res(null);
    });
  } catch { return null; }
}

/** Validates and stores the template. Throws SaveError if the file is not a usable save. */
export async function setTemplate(bytes: Uint8Array): Promise<AcwwSave> {
  const save = new AcwwSave(bytes);
  try {
    const db = await open();
    db.transaction(STORE, 'readwrite').objectStore(STORE).put(bytes.slice().buffer, KEY);
  } catch { /* storage unavailable: template only lives for this session */ }
  return save;
}

export async function clearTemplate(): Promise<void> {
  try { const db = await open(); db.transaction(STORE, 'readwrite').objectStore(STORE).delete(KEY); } catch { /* ignore */ }
}

export interface NewTownOptions {
  townName: string;
  playerName: string;
  villagers: number[]; // up to 8 species ids, NO_VILLAGER (0xff) for an empty slot
  wallet: number;
  bank: number;
  hairstyle: number; hairColor: number; face: number; tan: number;
  emptyPockets: boolean;
}

export function randomVillagers(n = 8): number[] {
  const pool = VILLAGERS.map(v => v.id);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  return pool.slice(0, n);
}

export function buildFromTemplate(template: Uint8Array, o: NewTownOptions): AcwwSave {
  const s = new AcwwSave(template);
  if (o.townName) s.townName = o.townName;
  const p = s.players.find(x => x.exists) ?? s.players[0];
  if (o.playerName) p.name = o.playerName;
  p.wallet = o.wallet; p.bank = o.bank;
  p.hairstyle = o.hairstyle; p.hairColor = o.hairColor; p.face = o.face; p.tan = o.tan;
  if (o.emptyPockets) for (let i = 0; i < 15; i++) p.setPocket(i, 0xfff1);
  // Only replace villagers in slots that already have one: an empty slot has no house in the template.
  const occupied = s.villagers.filter(v => v.exists);
  occupied.forEach((v, i) => { if (o.villagers[i] !== undefined) v.species = o.villagers[i]; });
  return s;
}
